import { type TeamHuntState } from "@hunt/public-client";
import React, { createContext, useContext } from "react";

const TeamStateContext = createContext<TeamHuntState | null>(null);

export const TeamStateProvider = ({
  teamState,
  children,
}: {
  teamState: TeamHuntState;
  children: React.ReactNode;
}) => {
  return (
    <TeamStateContext.Provider value={teamState}>
      {children}
    </TeamStateContext.Provider>
  );
};

export const useTeamState = () => {
  const teamState = useContext(TeamStateContext);
  if (!teamState) {
    throw new Error("TeamStateProvider not found");
  }
  return teamState;
};
