import { dontLeakThis } from "@hunt/anti-leak";
import { WORD_LIST } from "@hunt/hunt-data";

const newAlpha = dontLeakThis([
  "X",
  "W",
  "B",
  "A",
  "F",
  "E",
  "J",
  "I",
  "N",
  "M",
  "R",
  "Q",
  "V",
  "U",
  "Z",
  "Y",
  "D",
  "C",
  "H",
  "G",
  "L",
  "K",
  "P",
  "O",
  "T",
  "S",
]);

const k = (x: string) => x.split("").map((i) => newAlpha.indexOf(i));

const wordSet = new Set(WORD_LIST);

const compare = (x: number[], y: number[]): [1 | -1 | 0, number | null] => {
  const m = Math.min(x.length, y.length);
  for (let i = 0; i < m; i++) {
    if (x[i] < y[i]) {
      return [1, i];
    } else if (x[i] > y[i]) {
      return [-1, i];
    }
  }
  if (x.length < y.length) {
    return [1, m];
  } else if (x.length > y.length) {
    return [-1, m];
  } else {
    return [0, null];
  }
};

const searchNextWord = (s: string, order: boolean) => {
  let [low, high] = [0, WORD_LIST.length];
  while (high - low > 1) {
    const mid = Math.floor((low + high) / 2);
    if (
      order
        ? compare(k(WORD_LIST[mid]), k(s))[0] === 1
        : compare(k(WORD_LIST[mid]), k(s))[0] !== -1
    ) {
      low = mid;
    } else {
      high = mid;
    }
  }
  if (high - low !== 1) {
    throw new Error("Problem!");
  }
  return WORD_LIST[order ? low : high];
};

const ans = "STOP";

// We found out after hunt that going up to sixteenth (as before hunt)
// was not high enough, and added extra stuff at the end (the longest
// word in the wordlist that the puzzle uses is length 23).
const ordinals = [
  "x",
  "first",
  "second",
  "third",
  "fourth",
  "fifth",
  "sixth",
  "seventh",
  "eighth",
  "ninth",
  "tenth",
  "eleventh",
  "twelfth",
  "thirteenth",
  "fourteenth",
  "fifteenth",
  "sixteenth",
  "seventeenth",
  "eighteenth",
  "nineteenth",
  "twentieth",
  "twenty-first",
  "twenty-second",
  "twenty-third",
];

export const output = (s: string) => {
  s = s.toUpperCase().replace(/[^A-Z]/g, "");
  if (!s) {
    return "All answers must have at least one alphabetic character.";
  }
  if (!wordSet.has(s)) {
    return "The answer to this puzzle is an English word.";
  }
  const cmp = compare(k(s), k(ans));
  if (cmp[0] === 0) {
    return "Correct!";
  }
  const m = { "1": "Keep going!", "-1": "Go back!" }[cmp[0]];
  const w = searchNextWord(s, cmp[0] === -1);
  const common = compare(k(s), k(w))[1];
  if (common === null) {
    throw new Error("expected common to be non-null");
  } else if (common === 0) {
    return m + " Try submitting " + w + " instead.";
  } else if (common === s.length) {
    return m + " Add " + w.slice(common) + " at the end.";
  } else if (common === w.length) {
    return m + " Remove everything after the " + ordinals[common] + " letter.";
  } else {
    return (
      m +
      " Replace everything after the " +
      ordinals[common] +
      " letter with " +
      w.slice(common) +
      "."
    );
  }
};
