import {
  newClient,
  type TeamHuntState,
  type publicContract,
  type TaskSubmissionHistoryEntry,
} from "@hunt/public-client";
import { useGlobalVolume } from "@hunt/puzzle-components";
import { PrimarySearchField } from "@hunt/shadcn";
import { Button, cn } from "@hunt/styled-ui";
import { CheckCircle, Hourglass } from "lucide-react";
import React, { useCallback, useEffect, useRef, useState } from "react";
import { type z } from "zod";
import canonicalizeInput from "../../../lib/canonicalizeInput";
import { output as keepGoingOutput } from "../../../lib/keep_going";
import apiUrl from "../utils/apiUrl";
import { IS_STATIC_SITE, staticDisabledMessage } from "../utils/staticSite";
import { PuzzleComplete } from "./PuzzleComplete";
import { TeamStateProvider } from "./TeamStateProvider";
import { markLandOfNoNameSolved } from "./alphabet/landOfNoNameLocalState";
import { markPuzzleSolved } from "./puzzleSolveLocalState";

type GetPuzzleStateResponse = z.infer<
  (typeof publicContract.getPuzzleState.responses)["200"]
>;
type Guesses = GetPuzzleStateResponse["guesses"];
type Guess = Guesses[number];
type FormState = "idle" | "submitting" | "error";

const GUESS_WIDTH_CLASS = "max-w-[56rem]";
const CLIENT_RATE_LIMIT_MS = 1000;
const STATIC_KEEP_GOING_SLUG = "keep_going";

type StaticGuessConfig = {
  answer?: string;
  cannedResponses?: {
    guess: string[];
    reply: string;
    link?: { display: string; href: string };
  }[];
  tileMetaPartials?: string[];
  isKeepGoing?: boolean;
  solveSound?: string;
};

const getStaticGuessConfig = (): StaticGuessConfig | undefined => {
  if (typeof window === "undefined") {
    return undefined;
  }
  return (window as unknown as { staticGuessConfig?: StaticGuessConfig })
    .staticGuessConfig;
};

const findCannedResponse = (
  cannedResponses: StaticGuessConfig["cannedResponses"],
  canonicalGuess: string,
) =>
  cannedResponses?.find((response) =>
    response.guess.some(
      (candidate) => canonicalizeInput(candidate) === canonicalGuess,
    ),
  );

const PuzzleGuessForm = ({
  type,
  slug,
  onGuessesUpdate,
  errorMessageClassName,
  rateLimitMessageClassName,
  onSubmissionStart,
  inputContainerClassName,
  forcedInput,
  showSubmissionForm = true,
  googleFormsLink = "",
  inputBgColor,
  allowStaticSubmissions = false,
  existingGuesses = [],
  staticGuessConfig = getStaticGuessConfig(),
}: {
  type: "puzzle" | "subpuzzle";
  slug: string;
  onGuessesUpdate: (guesses: Guesses) => void;
  errorMessageClassName?: string;
  rateLimitMessageClassName?: string;
  onSubmissionStart?: () => void;
  inputContainerClassName?: string;
  forcedInput?: string;
  showSubmissionForm?: boolean;
  googleFormsLink?: string;
  inputBgColor?: string;
  allowStaticSubmissions?: boolean;
  existingGuesses?: Guesses;
  staticGuessConfig?: StaticGuessConfig;
}) => {
  const [guessInput, setGuessInput] = useState<string>(forcedInput ?? "");
  const [rateLimitedUntil, setRateLimitedUntil] = useState<Date | undefined>(
    undefined,
  );
  const rateLimitedUntilRef = useRef<Date | undefined>(undefined);
  const [clientRateLimitedUntil, setClientRateLimitedUntil] = useState<
    Date | undefined
  >(undefined);
  const clientRateLimitedUntilRef = useRef<Date | undefined>(undefined);
  const [formState, setFormState] = useState<FormState>("idle");
  const [formError, setFormError] = useState<string | undefined>(undefined);
  const inputRef = useRef<HTMLInputElement>(null);
  const inputFocusedOnSubmit = useRef<boolean>(false);
  const staticGuessIdRef = useRef<number>(0);
  const isStaticSite = IS_STATIC_SITE;
  const globalVolume = useGlobalVolume();
  const isStaticSubmissionDisabled = isStaticSite && !allowStaticSubmissions;
  const closedMessage = isStaticSubmissionDisabled
    ? staticDisabledMessage("Submissions")
    : googleFormsLink
      ? "Submission forms are closed in archival mode."
      : null;
  const showForm = showSubmissionForm && !isStaticSubmissionDisabled;
  const allowForcedSubmit =
    forcedInput && !showForm && !isStaticSubmissionDisabled;

  useEffect(() => {
    if (formState === "idle" && inputFocusedOnSubmit.current) {
      inputRef.current?.focus();
    }
  }, [formState]);

  const checkClearRateLimit = useCallback(() => {
    const now = new Date();
    const until = rateLimitedUntilRef.current;
    if (until !== undefined && until < now) {
      rateLimitedUntilRef.current = undefined;
      setRateLimitedUntil(undefined);
    }
  }, []);

  const checkClearClientRateLimit = useCallback(() => {
    const now = new Date();
    const until = clientRateLimitedUntilRef.current;
    if (until !== undefined && until < now) {
      clientRateLimitedUntilRef.current = undefined;
      setClientRateLimitedUntil(undefined);
    }
  }, []);

  const isCurrentlyRateLimited = useCallback(() => {
    const now = new Date();
    const serverUntil = rateLimitedUntilRef.current;
    const clientUntil = clientRateLimitedUntilRef.current;
    return (
      (serverUntil !== undefined && serverUntil > now) ||
      (clientUntil !== undefined && clientUntil > now)
    );
  }, []);

  const onInputChanged = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      setGuessInput(e.target.value);
    },
    [],
  );
  const staticAnswer = staticGuessConfig?.answer;
  const staticSolveSound = staticGuessConfig?.solveSound;

  const buildStaticGuessEntries = useCallback(
    (rawGuess: string) => {
      if (!staticGuessConfig) {
        return {
          entries: [],
          errorMessage: "Static guess checking is unavailable for this puzzle.",
        };
      }

      const entries: Guess[] = [];
      const timestamp = new Date().toISOString();
      const nextId = () => {
        staticGuessIdRef.current += 1;
        return Date.now() + staticGuessIdRef.current;
      };
      const pushEntry = (
        canonicalInput: string,
        status: Guess["status"],
        response: string,
        link?: Guess["link"],
      ) => {
        entries.push({
          id: nextId(),
          canonical_input: canonicalInput,
          status,
          response,
          timestamp,
          ...(link ? { link } : {}),
        });
      };

      const canonicalGuess = canonicalizeInput(rawGuess);
      const canonicalAnswer = staticGuessConfig.answer
        ? canonicalizeInput(staticGuessConfig.answer)
        : undefined;
      const cannedResponses = staticGuessConfig.cannedResponses ?? [];
      const tileMetaPartials = staticGuessConfig.tileMetaPartials ?? [];
      const canonicalPartials = tileMetaPartials.map(canonicalizeInput);
      const combinedForward = canonicalPartials.join("");
      const combinedReverse = [...canonicalPartials].reverse().join("");
      const normalizedGuess =
        canonicalGuess === combinedReverse ? combinedForward : canonicalGuess;
      const isTileMeta = canonicalPartials.length > 0;
      const isCombinedGuess = isTileMeta && normalizedGuess === combinedForward;
      const isKeepGoing =
        staticGuessConfig.isKeepGoing ?? slug === STATIC_KEEP_GOING_SLUG;

      const existingCanonicalSet = new Set(
        existingGuesses.map((guess) =>
          canonicalizeInput(guess.canonical_input),
        ),
      );

      const addMissingPartials = () => {
        canonicalPartials.forEach((partial, index) => {
          if (existingCanonicalSet.has(partial)) {
            return;
          }
          const displayPartial = tileMetaPartials[index] ?? partial;
          const cannedPartial = findCannedResponse(cannedResponses, partial);
          pushEntry(
            displayPartial,
            "other",
            cannedPartial?.reply ?? "Correct!",
            cannedPartial?.link,
          );
          existingCanonicalSet.add(partial);
        });
      };

      const partialIndex = isTileMeta
        ? canonicalPartials.indexOf(normalizedGuess)
        : -1;

      if (partialIndex !== -1) {
        const displayPartial = tileMetaPartials[partialIndex];
        const cannedPartial = findCannedResponse(
          cannedResponses,
          canonicalPartials[partialIndex],
        );
        pushEntry(
          displayPartial,
          "other",
          cannedPartial?.reply ?? "Correct!",
          cannedPartial?.link,
        );
        existingCanonicalSet.add(canonicalPartials[partialIndex]);
      } else if (!isCombinedGuess) {
        let status: Guess["status"] = "incorrect";
        let response = "Incorrect";
        let link: Guess["link"] | undefined;
        let canonicalInput = canonicalGuess;

        if (canonicalAnswer && canonicalGuess === canonicalAnswer) {
          status = "correct";
          response = "Correct!";
          canonicalInput = staticGuessConfig.answer ?? canonicalGuess;
          existingCanonicalSet.add(canonicalAnswer);
        } else if (isKeepGoing) {
          response = keepGoingOutput(canonicalGuess);
        } else {
          const canned = findCannedResponse(cannedResponses, canonicalGuess);
          if (canned) {
            const matchingInput = canned.guess.find(
              (candidate) => canonicalizeInput(candidate) === canonicalGuess,
            );
            canonicalInput = matchingInput ?? canonicalInput;
            response = canned.reply;
            status = "other";
            link = canned.link;
          }
        }

        pushEntry(canonicalInput, status, response, link);
      }

      if (isTileMeta) {
        const hasAllPartials = canonicalPartials.every((partial) =>
          existingCanonicalSet.has(partial),
        );
        const shouldAutoSolve = isCombinedGuess || hasAllPartials;
        if (shouldAutoSolve) {
          addMissingPartials();
          if (canonicalAnswer && !existingCanonicalSet.has(canonicalAnswer)) {
            pushEntry(
              staticGuessConfig.answer ?? canonicalAnswer,
              "correct",
              "Correct! (auto-submitted)",
            );
            existingCanonicalSet.add(canonicalAnswer);
          }
        } else if (
          canonicalAnswer &&
          existingCanonicalSet.has(canonicalAnswer)
        ) {
          addMissingPartials();
        }
      }

      return { entries };
    },
    [existingGuesses, slug, staticGuessConfig],
  );

  const onSubmit = useCallback(
    (e: React.FormEvent<HTMLFormElement>) => {
      e.preventDefault();
      inputFocusedOnSubmit.current =
        inputRef.current === document.activeElement;
      checkClearRateLimit();
      checkClearClientRateLimit();
      if (IS_STATIC_SITE && allowStaticSubmissions) {
        if (formState === "submitting" || isCurrentlyRateLimited()) {
          return;
        }
        setFormState("submitting");
        onSubmissionStart?.();
        const { entries, errorMessage } = buildStaticGuessEntries(guessInput);
        if (errorMessage) {
          setFormError(errorMessage);
          setFormState("error");
          return;
        }
        const alreadySolved = existingGuesses.some(
          (guess) => guess.status === "correct",
        );
        const solveSound = staticSolveSound;
        const shouldPlaySolveSound =
          !alreadySolved &&
          entries.some((entry) => entry.status === "correct") &&
          Boolean(solveSound);
        setGuessInput("");
        setFormError(undefined);
        setFormState("idle");
        if (entries.length > 0) {
          onGuessesUpdate(entries);
        }
        if (entries.some((entry) => entry.status === "correct")) {
          markLandOfNoNameSolved(slug);
          if (type === "puzzle") {
            markPuzzleSolved(slug, staticAnswer);
          }
        }
        if (shouldPlaySolveSound && solveSound) {
          const audio = new Audio(solveSound);
          audio.volume = globalVolume;
          void audio.play().catch((error: unknown) => {
            console.error("Failed to play solve sound:", error);
          });
        }
        return;
      }
      if (IS_STATIC_SITE && !allowStaticSubmissions) {
        setFormError(staticDisabledMessage("Submissions"));
        setFormState("error");
        return;
      }
      if (formState === "submitting" || isCurrentlyRateLimited()) {
        return;
      }
      const now = new Date();
      const clientUntil = new Date(now.getTime() + CLIENT_RATE_LIMIT_MS);
      setClientRateLimitedUntil(clientUntil);
      clientRateLimitedUntilRef.current = clientUntil;
      // Add a 10ms buffer to avoid date-time imprecision
      // (probably more than needed but fine to be safe).
      setTimeout(checkClearClientRateLimit, CLIENT_RATE_LIMIT_MS + 10);
      setFormState("submitting");
      onSubmissionStart?.();

      void (async () => {
        let result;
        try {
          const apiClient = newClient(apiUrl(), undefined);
          if (type === "puzzle") {
            result = await apiClient.submitGuess({
              body: { guess: guessInput },
              params: { slug },
            });
          } else {
            // For gacha rounds, use submitQuest instead of submitSubpuzzleGuess
            if (slug.includes("fates_thread_casino")) {
              // Extract bannerSlug and questSlug from the slug
              const parts = slug.split("/");
              const bannerSlug = parts[1] || "";
              const questSlug = parts[2] || "";
              result = await apiClient.submitQuest({
                body: { guess: guessInput },
                params: { bannerSlug, questSlug },
              });
            } else {
              result = await apiClient.submitSubpuzzleGuess({
                body: { guess: guessInput },
                params: { slug },
              });
            }
          }
        } catch {
          setFormError("Network request failed");
          setFormState("error");
          return;
        }
        if (result.status === 200) {
          const parsedResult = result.body;
          setGuessInput("");
          setFormError(undefined);
          setFormState("idle");
          onGuessesUpdate(parsedResult.guesses);
        } else if (result.status === 429) {
          setFormError(undefined);
          const then = new Date(result.body.retryAfter);
          const now = new Date();
          setRateLimitedUntil(then);
          rateLimitedUntilRef.current = then;
          setTimeout(
            checkClearRateLimit,
            then.getTime() - now.getTime() + 1000,
          );
          setFormState("idle");
        } else {
          const errorMessage =
            result.body &&
            typeof result.body === "object" &&
            "error_message" in result.body &&
            typeof result.body.error_message === "string"
              ? result.body.error_message
              : `Server returned status ${result.status}`;
          setFormError(errorMessage);
          setFormState("error");
        }
      })();
    },
    [
      allowStaticSubmissions,
      buildStaticGuessEntries,
      guessInput,
      existingGuesses,
      staticAnswer,
      staticSolveSound,
      globalVolume,
      slug,
      type,
      checkClearRateLimit,
      checkClearClientRateLimit,
      formState,
      isCurrentlyRateLimited,
      onGuessesUpdate,
      onSubmissionStart,
    ],
  );

  const formDisabled = formState === "submitting";
  const submitDisabled =
    formDisabled ||
    rateLimitedUntil !== undefined ||
    clientRateLimitedUntil !== undefined;

  return (
    <form
      method="post"
      action={`/${type === "puzzle" ? "puzzles" : "subpuzzles"}/${slug}/guess`}
      onSubmit={onSubmit}
      className="flex flex-col justify-center"
    >
      {formError && (
        <div
          className={cn(
            "py-2 px-4 bg-red-500 mb-2 font-sans text-base text-white",
            errorMessageClassName,
          )}
        >
          Error: {formError}
        </div>
      )}
      {rateLimitedUntil && (
        <div
          id="rate-limit-notice"
          className={cn(
            "px-4 bg-white/60 mb-2 font-sans text-base text-red-900 mx-auto",
            rateLimitMessageClassName,
          )}
        >
          Your submissions are being rate-limited and will be rejected until{" "}
          {rateLimitedUntil.toLocaleTimeString()}
        </div>
      )}
      <div
        className={cn(
          "flex w-full flex-col items-center justify-center gap-2",
          GUESS_WIDTH_CLASS,
          inputContainerClassName,
        )}
      >
        {closedMessage && <div>{closedMessage}</div>}
        {allowForcedSubmit ? (
          <>
            <input
              id="guess-input"
              name="guess"
              type="hidden"
              required
              disabled={formDisabled}
              value={guessInput}
              onChange={onInputChanged}
              ref={inputRef}
            />
            <Button type="submit" disabled={submitDisabled}>
              Submit
            </Button>
          </>
        ) : (
          showForm && (
            <div className="relative flex w-full max-w-2xl items-center justify-center">
              <PrimarySearchField
                id="guess-input"
                name="guess"
                type="text"
                value={guessInput}
                onChange={onInputChanged}
                ref={inputRef}
                placeholder={
                  formDisabled ? "Loading..." : "Submit guess here..."
                }
                disabled={formDisabled}
                required
                buttonProps={{
                  type: "submit",
                  disabled: submitDisabled,
                  "aria-label": "Submit guess",
                }}
                className={inputBgColor}
              />
            </div>
          )
        )}
      </div>
    </form>
  );
};

function formatGuessTimestamp(t: string) {
  const timestamp = new Date(t);
  return {
    long: timestamp.toLocaleString(),
    short: timestamp.toLocaleString("en-US", {
      month: "numeric",
      day: "numeric",
      hour: "numeric",
      minute: "2-digit",
    }),
  };
}

// Client-side only timestamp formatter to avoid SSR timezone issues
const ClientTimestamp = ({
  timestamp,
  className,
}: {
  timestamp: string;
  className?: string;
}) => {
  const [formatted, setFormatted] = useState<{
    long: string;
    short: string;
  } | null>(null);

  useEffect(() => {
    // Only format on the client after mount
    setFormatted(formatGuessTimestamp(timestamp));
  }, [timestamp]);

  // During SSR and before hydration, show a placeholder or nothing
  if (formatted === null) {
    return <span className={className}>—</span>;
  }

  return (
    <>
      <span className={cn("hidden lg:inline", className)}>
        {formatted.long}
      </span>
      <span className={cn("lg:hidden", className)}>{formatted.short}</span>
    </>
  );
};

const PuzzleResponse = ({
  link,
  response,
  status,
}: Pick<Guess, "link" | "response" | "status">): React.JSX.Element => {
  return (
    <td
      className={cn(
        "whitespace-pre-wrap px-6 py-2 font-nova text-base align-middle",
        status === "correct" ? "text-accent" : "text-white/90",
      )}
    >
      {response}
      {link && (
        <a
          href={link.href}
          target="_blank"
          rel="noreferrer"
          className="ml-2 text-accent underline-offset-4 hover:underline"
        >
          {link.display}
        </a>
      )}
    </td>
  );
};

const PuzzleGuessHistoryTable = ({
  guesses,
  className,
}: {
  guesses: Guesses;
  className?: string;
}) => {
  if (guesses.length === 0) {
    return null;
  }
  return (
    <div
      className={cn(
        "w-full mx-auto rounded-3xl overflow-hidden border-2 border-secondary bg-primary",
        GUESS_WIDTH_CLASS,
        className,
      )}
    >
      <table
        id="guess-history"
        className="w-full text-left font-sans text-white"
      >
        <thead>
          <tr className="bg-secondary text-white text-lg font-nova">
            <th className="px-6 py-2">Guess</th>
            <th className="px-6 py-2">Response</th>
            <th className="px-6 py-2">Time</th>
          </tr>
        </thead>
        <tbody>
          {guesses.toReversed().map((g) => {
            return (
              <tr
                key={g.canonical_input}
                className="rounded-2xl text-base text-white"
              >
                <td
                  className={cn(
                    "px-6 py-2 font-mono text-lg font-black uppercase tracking-[0.08em]",
                    g.status === "correct" ? "text-accent" : "text-white",
                  )}
                >
                  {g.canonical_input}
                </td>
                <PuzzleResponse
                  link={g.link}
                  response={g.response}
                  status={g.status}
                />
                <td
                  className={cn(
                    "px-6 py-2 text-base font-medium font-nova",
                    g.status === "correct" ? "text-accent" : "text-white/90",
                  )}
                >
                  <ClientTimestamp timestamp={g.timestamp} />
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
};

const TaskSubmissionHistoryTable = ({
  submissions,
  className,
}: {
  submissions: TaskSubmissionHistoryEntry[];
  className?: string;
}) => {
  if (submissions.length === 0) {
    return null;
  }

  return (
    <div
      className={cn(
        "w-full mx-auto rounded-3xl overflow-hidden border-2 border-secondary bg-primary",
        GUESS_WIDTH_CLASS,
        className,
      )}
    >
      <table className="w-full text-left font-sans text-white">
        <thead>
          <tr className="bg-secondary text-white text-lg font-nova">
            <th className="px-6 py-2">Status</th>
            <th className="px-6 py-2">Feedback</th>
            <th className="px-6 py-2">Time</th>
          </tr>
        </thead>
        <tbody>
          {submissions.toReversed().map((submission, index) => {
            const statusConfig = {
              pending: {
                label: "Pending Review",
                color: "text-amber-400",
              },
              incorrect: {
                label: "Incorrect",
                color: "text-red-400",
              },
              correct: {
                label: "Correct",
                color: "text-accent",
              },
            }[submission.status];

            return (
              <tr
                key={submission.id ?? index}
                className="rounded-2xl text-base text-white"
              >
                <td
                  className={cn(
                    "px-6 py-2 text-lg font-bold font-nova",
                    statusConfig.color,
                  )}
                >
                  {statusConfig.label}
                </td>
                <td className="px-6 py-2 text-base text-white/90">
                  {submission.feedback || "—"}
                </td>
                <td
                  className={cn(
                    "px-6 py-2 text-base font-medium font-nova",
                    submission.status === "correct"
                      ? "text-accent"
                      : "text-white/90",
                  )}
                >
                  <ClientTimestamp timestamp={submission.timestamp} />
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
};

const PuzzleGuessSection = ({
  slug,
  guesses,
  onGuessesUpdate,
  teamState,
  showTaskDev,
  showSubmissionForm = true,
  googleFormsLink = "",
  taskSubmissionState,
  taskSubmissions,
  inputBgColor,
}: {
  slug: string;
  guesses: Guesses;
  onGuessesUpdate: (guesses: Guesses) => void;
  teamState: TeamHuntState;
  showTaskDev?: boolean;
  showSubmissionForm?: boolean;
  googleFormsLink?: string;
  taskSubmissionState?: "submittable" | "pending_grade" | "complete";
  taskSubmissions?: TaskSubmissionHistoryEntry[];
  inputBgColor?: string;
}) => {
  const puzzleState = teamState.puzzles[slug];
  const isTask = puzzleState?.task_info !== undefined;
  const isReplayable = puzzleState?.task_info?.replayable === true;
  const solved =
    guesses.some((g) => g.status === "correct") ||
    (isTask && puzzleState.solved);
  // Task submission state is normally provided by the server route, but on the
  // static site we may only have it in teamState (or not at all). If it's
  // missing, default to showing the submission UI so answer-submittable tasks
  // still render the guess section.
  const resolvedTaskSubmissionState =
    taskSubmissionState ?? puzzleState?.task_submission_state;
  const solutionAvailable =
    teamState.gates_satisfied.includes("solutions_released");
  const puzzleRoundHref = puzzleState?.round
    ? `/rounds/${puzzleState.round}`
    : undefined;

  let forcedInput: string | undefined;
  if (showTaskDev && !showSubmissionForm) {
    // Disable dev mode task submission for testsolve.
    //  forcedInput = "COMPLETE_TASK_DEV";
    forcedInput = undefined;
  } else {
    forcedInput = undefined;
  }

  // Determine if we should show the submission form
  // For replayable tasks, allow showing form even when solved or complete
  const shouldShowForm =
    (!solved || isReplayable) &&
    (!isTask ||
      resolvedTaskSubmissionState === undefined ||
      resolvedTaskSubmissionState === "submittable" ||
      (isReplayable && resolvedTaskSubmissionState === "complete"));
  const isPendingGrade =
    isTask && resolvedTaskSubmissionState === "pending_grade";
  const isComplete = isTask && resolvedTaskSubmissionState === "complete";
  const isEventTask =
    isTask && puzzleState?.task_info?.submission_type === "event";
  const requiresScheduling =
    (isEventTask && puzzleState?.task_info?.requires_scheduling) ||
    puzzleState?.requires_scheduling;
  const isGameworldTask =
    isTask && puzzleState?.task_info?.submission_type === "gameworld";
  const isAbandonedShrineTask = slug === "abandoned_shrine";
  const staticGuessConfig = getStaticGuessConfig();
  // This is a catch-all for tasks that aren't events, manual submission, or gameworld.
  const isTaskCompleteableOnPage =
    isTask &&
    !googleFormsLink &&
    !showSubmissionForm &&
    !isEventTask &&
    !isGameworldTask;
  const shouldShowTaskBanner =
    isTask &&
    (isTaskCompleteableOnPage || (isGameworldTask && !isAbandonedShrineTask));
  const shouldShowGuessHistory = !isTask || showSubmissionForm;

  return (
    <section id="puzzle-guess-section">
      <TeamStateProvider teamState={teamState}>
        <div className="flex flex-col items-center gap-4">
          {/* Show scheduling instructions for event-type tasks */}
          {shouldShowForm && requiresScheduling && (
            <div className="w-full max-w-2xl mx-auto rounded-3xl border-2 border-secondary bg-primary text-xl text-white text-center py-2 px-4">
              {!IS_STATIC_SITE && googleFormsLink ? (
                <>
                  Use this{" "}
                  <a
                    href={googleFormsLink}
                    target="_blank"
                    rel="noreferrer"
                    className="text-accent underline-offset-4 hover:underline hover:text-[#BEF1FF]"
                  >
                    Google Form
                  </a>{" "}
                  to request a time slot.
                </>
              ) : (
                "Scheduling is unavailable in archival mode."
              )}
            </div>
          )}
          {shouldShowTaskBanner && (
            <div className="w-full max-w-2xl mx-auto rounded-3xl border-2 border-secondary bg-primary text-xl text-white text-center py-2 px-4">
              {isGameworldTask && !isAbandonedShrineTask && (
                <>
                  This task requires{" "}
                  {puzzleRoundHref ? (
                    <a
                      href={puzzleRoundHref}
                      className="text-accent underline-offset-4 hover:underline hover:text-[#BEF1FF]"
                    >
                      MonQuest
                    </a>
                  ) : (
                    "MonQuest"
                  )}
                  .
                </>
              )}
              {isTaskCompleteableOnPage && "Complete the task below."}
            </div>
          )}
          {/* Show regular task submission form for non-event tasks */}
          {shouldShowForm &&
            isTask &&
            (showSubmissionForm ||
              (googleFormsLink && !requiresScheduling)) && (
              <div className="w-full max-w-2xl mx-auto">
                {/* For non-scheduling tasks, show the Google Form link here.
                  Scheduling tasks are handled above so we don't show it twice. */}
                {googleFormsLink && !requiresScheduling && (
                  <div className="rounded-3xl border-2 border-secondary bg-primary text-xl text-white text-center py-2 px-4">
                    {!IS_STATIC_SITE ? (
                      <span>
                        Use this{" "}
                        <a
                          href={googleFormsLink}
                          target="_blank"
                          rel="noreferrer"
                          className="text-accent underline-offset-4 hover:underline hover:text-[#BEF1FF]"
                        >
                          Google Form
                        </a>{" "}
                        to send us your submission.
                      </span>
                    ) : (
                      <span>
                        Submission forms are unavailable in archival mode.
                      </span>
                    )}
                  </div>
                )}
                <PuzzleGuessForm
                  type="puzzle"
                  slug={slug}
                  onGuessesUpdate={onGuessesUpdate}
                  forcedInput={forcedInput}
                  showSubmissionForm={showSubmissionForm}
                  googleFormsLink=""
                  inputContainerClassName="max-w-full"
                  inputBgColor={inputBgColor}
                  allowStaticSubmissions={true}
                  existingGuesses={guesses}
                  staticGuessConfig={staticGuessConfig}
                />
              </div>
            )}
          {shouldShowForm && !isTask && (
            <div className={cn("w-full", GUESS_WIDTH_CLASS)}>
              <PuzzleGuessForm
                type="puzzle"
                slug={slug}
                onGuessesUpdate={onGuessesUpdate}
                forcedInput={forcedInput}
                showSubmissionForm={showSubmissionForm}
                googleFormsLink={googleFormsLink}
                inputBgColor={inputBgColor}
                allowStaticSubmissions={true}
                existingGuesses={guesses}
                staticGuessConfig={staticGuessConfig}
              />
            </div>
          )}
          {isPendingGrade && (
            <div className="w-full max-w-md mx-auto">
              <div className="rounded-3xl border-2 border-secondary bg-primary overflow-hidden">
                <div className="flex flex-col items-center">
                  {/* Icon section with darker background (top) */}
                  <div className="w-full flex items-center justify-center py-6 bg-secondary">
                    <div className="relative">
                      <Hourglass
                        className="relative h-12 w-12 text-red-500 z-10"
                        strokeWidth={2}
                      />
                      {/* Icon shadow */}
                      <Hourglass
                        className="absolute left-1 top-1.5 h-12 w-12 text-[#0B1D31] stroke-[#0B1D31] z-0"
                        strokeWidth={2}
                      />
                    </div>
                  </div>
                  {/* Text section (bottom) */}
                  <div className="w-full px-6 py-6 text-center">
                    <p className="text-xl font-semibold text-white">
                      Submission pending review
                    </p>
                  </div>
                </div>
              </div>
            </div>
          )}
          {isComplete && (
            <div className="w-full max-w-md mx-auto">
              <div className="rounded-3xl border-2 border-secondary bg-primary overflow-hidden">
                <div className="flex flex-col items-center">
                  {/* Icon section with darker background (top) */}
                  <div className="w-full flex items-center justify-center py-6 bg-secondary">
                    <div className="relative">
                      <CheckCircle
                        className="relative h-12 w-12 text-accent-green z-10"
                        strokeWidth={2}
                      />
                      {/* Icon shadow */}
                      <CheckCircle
                        className="absolute left-1 top-1.5 h-12 w-12 text-[#0B1D31] stroke-[#0B1D31] z-0"
                        strokeWidth={2}
                      />
                    </div>
                  </div>
                  {/* Text section (bottom) */}
                  <div className="w-full px-6 py-6 text-center">
                    <p className="text-xl font-semibold text-white">
                      Task Complete!
                    </p>
                  </div>
                </div>
              </div>
            </div>
          )}
          {/* Task Submission History */}
          {isTask && taskSubmissions && taskSubmissions.length > 0 && (
            <TaskSubmissionHistoryTable
              submissions={taskSubmissions}
              className="mt-6"
            />
          )}
          <div className={cn("relative w-full", GUESS_WIDTH_CLASS)}>
            {solved && (
              <PuzzleComplete
                className="pointer-events-none absolute -right-16 top-8 -translate-y-[20%] sm:-right-16 sm:top-10 sm:-translate-y-[25%] md:-right-16"
                message={isTask ? "Task Complete!" : undefined}
              />
            )}
            {shouldShowGuessHistory && (
              <PuzzleGuessHistoryTable
                guesses={guesses}
                className={solved ? "mt-2" : "mt-6"}
              />
            )}
            {solutionAvailable && (
              <div
                className={cn(
                  "solutions-link text-center",
                  shouldShowGuessHistory && guesses.length > 0
                    ? "mt-4"
                    : "mt-0",
                )}
              >
                <div className="inline-flex flex-wrap items-center justify-center gap-2">
                  <a
                    href={`${isTask ? "/research_tasks" : "/puzzles"}/${slug}/solution`}
                    className="inline-block no-underline h-fit w-fit px-3 py-2 rounded-md border-2 border-secondary mx-auto bg-secondary text-white text-center hover:bg-primary hover:border-primary hover:text-accent focus-visible:bg-primary focus-visible:border-primary focus-visible:text-accent"
                  >
                    View solution
                  </a>
                  <a
                    href={`${isTask ? "/research_tasks" : "/puzzles"}/${slug}/stats`}
                    className="inline-block no-underline h-fit w-fit px-3 py-2 rounded-md border-2 border-secondary mx-auto bg-secondary text-white text-center hover:bg-primary hover:border-primary hover:text-accent focus-visible:bg-primary focus-visible:border-primary focus-visible:text-accent"
                  >
                    View stats
                  </a>
                </div>
              </div>
            )}
          </div>
        </div>
      </TeamStateProvider>
    </section>
  );
};

export default PuzzleGuessSection;

export function SubpuzzleGuessSection({
  slug,
  guesses,
  onGuessesUpdate,
  className = "",
  errorMessageClassName,
  rateLimitMessageClassName,
  inputContainerClassName,
  showSubmissionForm = true,
}: {
  slug: string;
  guesses: Guesses;
  onGuessesUpdate: (guesses: Guesses) => void;
  className?: string;
  errorMessageClassName?: string;
  rateLimitMessageClassName?: string;
  inputContainerClassName?: string;
  showSubmissionForm?: boolean;
}): React.JSX.Element {
  const solved = guesses.some((g) => g.status === "correct");

  return (
    <section
      id="puzzle-guess-section"
      className={cn("flex flex-col gap-4 print:hidden", className)}
    >
      {solved ? null : (
        <PuzzleGuessForm
          type="subpuzzle"
          slug={slug}
          onGuessesUpdate={onGuessesUpdate}
          errorMessageClassName={errorMessageClassName}
          rateLimitMessageClassName={rateLimitMessageClassName}
          inputContainerClassName={inputContainerClassName}
          showSubmissionForm={showSubmissionForm}
        />
      )}
      <PuzzleGuessHistoryTable guesses={guesses} className="mt-6" />
    </section>
  );
}
